INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Phishing-Angriff immer durch E-Mails erfolgt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch SMS oder Social Media möglich"}, {"text": "Ja", "correct": false, "because": "Andere Kanäle ebenfalls genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme schützt am besten vor unbefugtem Zugriff auf ein System?', 3, '[{"text": "Mehrfaktor-Authentifizierung", "correct": true, "because": "Erhöht Sicherheit durch mehrere Ebenen"}, {"text": "Lange Passwörter", "correct": false, "because": "Wichtig, aber nicht ausreichend"}, {"text": "Regelmäßige Updates", "correct": false, "because": "Schützt vor Schwachstellen, nicht direkt Zugriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Angriffe sind in einem WLAN-Netzwerk besonders kritisch?', 5, '[{"text": "Man-in-the-Middle", "correct": true, "because": "Abhören von Daten möglich"}, {"text": "Evil-Twin-Angriffe", "correct": true, "because": "Täuscht legitime Netzwerke vor"}, {"text": "Hohe Latenz", "correct": false, "because": "Kein Angriff"}, {"text": "Geräteüberlastung", "correct": false, "because": "Kein Sicherheitsproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein DDoS-Angriff zielt auf Datenklau. b) Ein Trojaner verschafft dauerhaften Zugriff.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "DDoS zielt auf Überlastung"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Netzwerk gegen externe Angriffe absichere?', 4, '[{"text": "Firewall-Konfiguration", "correct": false, "because": "Schutz vor externem Zugriff"}, {"text": "Intrusion Detection", "correct": false, "because": "Erkennt Angriffe"}, {"text": "Betriebssystemtyp", "correct": true, "because": "Nicht primär für Netzwerksicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Antivirenprogramme vor allen Bedrohungen schützen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nur gegen bekannte Malware effektiv"}, {"text": "Ja", "correct": false, "because": "Zero-Day-Angriffe ausgeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool hilft mir, Schwachstellen in einem System frühzeitig zu erkennen?', 3, '[{"text": "Vulnerability Scanner", "correct": true, "because": "Findet bekannte Schwachstellen"}, {"text": "Netzwerkanalysator", "correct": false, "because": "Analysiert Verkehr, nicht Schwachstellen"}, {"text": "Backup-Software", "correct": false, "because": "Schützt Daten, erkennt nichts"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen mindern das Risiko von Insider-Bedrohungen?', 5, '[{"text": "Zugriffsbeschränkungen", "correct": true, "because": "Begrenzt unbefugte Aktionen"}, {"text": "Protokollierung", "correct": true, "because": "Erkennt verdächtige Aktivitäten"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Sicherheitsfaktor"}, {"text": "Öffentliche Freigaben", "correct": false, "because": "Erhöht Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) SQL-Injection nur Datenbanken betrifft und b) starke Passwörter sie verhindern. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Passwörter schützen nicht vor Injection"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um ein System vor Social Engineering zu schützen?', 4, '[{"text": "Schulungen für Mitarbeiter", "correct": false, "because": "Erhöht Awareness"}, {"text": "Verifizierungsprozesse", "correct": false, "because": "Bestätigt Identitäten"}, {"text": "Grafikkartenleistung", "correct": true, "because": "Irrelevant für Sicherheitsmaßnahmen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein VPN immer sicher vor Datenlecks?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Konfiguration"}, {"text": "Ja", "correct": false, "because": "Schwachstellen möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen ein Passwort unsicher?', 4, '[{"text": "Wiederverwendung", "correct": true, "because": "Erhöht Kompromittierungsrisiko"}, {"text": "Kurze Länge", "correct": true, "because": "Leichter zu knacken"}, {"text": "Zufällige Zeichen", "correct": false, "because": "Erhöht Sicherheit"}, {"text": "Spezialzeichen", "correct": false, "because": "Erschwert Angriffe"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Verschlüsselung alle Datenprobleme löst. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Schützt nur Vertraulichkeit, nicht Integrität"}, {"text": "Ja", "correct": false, "because": "Andere Maßnahmen nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verhalten priorisiere ich, um Bedrohungen durch veraltete Software zu minimieren?', 3, '[{"text": "Regelmäßige Updates", "correct": true, "because": "Schließt bekannte Schwachstellen"}, {"text": "Manuelle Konfiguration", "correct": false, "because": "Nicht primär relevant"}, {"text": "Hohe Speicherkapazität", "correct": false, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein IDS erkennt Angriffe. b) Es blockiert sie automatisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Blockieren ist Aufgabe eines IPS"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Netzwerksegmentierung gegen Angriffe?', 5, '[{"text": "Begrenzt Schadensausbreitung", "correct": true, "because": "Isoliert betroffene Bereiche"}, {"text": "Erschwert lateralen Zugriff", "correct": true, "because": "Angreifer brauchen mehr Schritte"}, {"text": "Erhöht Bandbreite", "correct": false, "because": "Kein Sicherheitsvorteil"}, {"text": "Vereinfacht Passwörter", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Absicherung eines Servers unwichtig?', 3, '[{"text": "Patch-Management", "correct": false, "because": "Schließt Schwachstellen"}, {"text": "Zugriffskontrollen", "correct": false, "because": "Verhindert unbefugten Zugriff"}, {"text": "Monitorauflösung", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erkennt ein SIEM-System nur externe Bedrohungen?', 3, '[{"text": "Nein", "correct": true, "because": "Analysiert auch interne Aktivitäten"}, {"text": "Ja", "correct": false, "because": "Umfassende Überwachung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Brute-Force-Angriff immer erfolgreich ist?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Passwortstärke und Schutz"}, {"text": "Ja", "correct": false, "because": "Kann durch Sperren verhindert werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik wähle ich, um einen Ransomware-Angriff zu verhindern?', 4, '[{"text": "Regelmäßige Backups", "correct": true, "because": "Ermöglicht Wiederherstellung ohne Lösegeld"}, {"text": "Schnelle Prozessoren", "correct": false, "because": "Kein Schutz vor Malware"}, {"text": "Hohe Speicherkapazität", "correct": false, "because": "Nicht sicherheitsrelevant"}]');
